import os, json, csv, re, io, xml.etree.ElementTree as ET

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def parse_json(p):
    with open(p, encoding="utf-8") as f:
        d = json.load(f)
    rows = d.get("rows", [])
    statuses = [r.get("status") for r in rows]
    entities = [r.get("entity_key") for r in rows]
    return {
        "id": d.get("record_id"), "pk": d.get("portfolio_key"), "role": d.get("evidence_role"),
        "subject": d.get("subject"), "ent": d.get("immutable_entity_key"),
        "ref_rev": d.get("referenced_revision"), "cur_rev": d.get("current_revision"),
        "custodian": d.get("custodian"), "reviewer": d.get("reviewer"),
        "body": d.get("body"), "statuses": statuses, "entities": entities,
    }

def parse_csv(p):
    with open(p, encoding="utf-8") as f:
        rows = list(csv.reader(f))
    # header row + data; find control table
    text = open(p, encoding="utf-8").read()
    return parse_textish(text)

def parse_xml(p):
    text = open(p, encoding="utf-8").read()
    return parse_textish(text)

def parse_md(p):
    return parse_textish(open(p, encoding="utf-8").read())

def parse_txt(p):
    return parse_textish(open(p, encoding="utf-8").read())

def parse_eml(p):
    return parse_textish(open(p, encoding="utf-8").read())

def parse_html(p):
    return parse_textish(open(p, encoding="utf-8").read())

def parse_textish(text):
    def grab(label):
        m = re.search(label + r"\s*[:|=]\s*([^\n|]+)", text)
        return m.group(1).strip() if m else None
    pk = grab(r"(?i)portfolio[_ ]?key")
    role = grab(r"(?i)evidence[_ ]?role")
    subject = grab(r"(?i)subject")
    ent = grab(r"(?i)immutable[_ ]?entity")
    ref_rev = grab(r"(?i)referenced[_ ]?revision")
    cur_rev = grab(r"(?i)current[_ ]?revision")
    custodian = grab(r"(?i)custodian")
    reviewer = grab(r"(?i)reviewer")
    rid = re.search(r"CB-DOC-031-\d{3}", text)
    rid = rid.group(0) if rid else None
    # native record body
    body = None
    m = re.search(r"(?i)Native record\s*\n\n(.+?)(?:\n\n##|\n\n#)", text, re.S)
    if not m:
        m = re.search(r"(?i)(?:^|\n)> (.+?)(?:\n|$)", text)
    # statuses & entities from rows
    statuses = re.findall(r"\b(confirmed|recorded|pending|superseded)\b", text)
    entities = re.findall(r"ENT-031-\d{4}", text)
    return dict(id=rid, pk=pk, role=role, subject=subject, ent=ent,
                ref_rev=ref_rev, cur_rev=cur_rev, custodian=custodian, reviewer=reviewer,
                body=body, statuses=statuses, entities=entities)

records = []
for cat in sorted(os.listdir(base)):
    d = os.path.join(base, cat)
    if not os.path.isdir(d): continue
    for f in sorted(os.listdir(d)):
        if f.endswith(".xlsx"): continue
        p = os.path.join(d, f)
        try:
            if f.endswith(".json"): r = parse_json(p)
            elif f.endswith(".csv"): r = parse_csv(p)
            elif f.endswith(".xml"): r = parse_xml(p)
            elif f.endswith(".md"): r = parse_md(p)
            elif f.endswith(".txt"): r = parse_txt(p)
            elif f.endswith(".eml"): r = parse_eml(p)
            elif f.endswith(".html"): r = parse_html(p)
            elif f.endswith(".pdf"): r = None
            else: r = None
        except Exception as e:
            r = dict(id=f, err=str(e))
        if r:
            r["file"] = f
            records.append(r)

print("TOTAL parsed:", len(records))
# Print compact table
for r in sorted(records, key=lambda x: x.get("id") or ""):
    print(f"{r.get('id'):>14} | pk={r.get('pk')} | role={r.get('role')} | subj={r.get('subject')} | ent={r.get('ent')} | ref={r.get('ref_rev')} | cur={r.get('cur_rev')} | file={r.get('file')}")
"}

