import os, json, re
from pypdf import PdfReader

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"
CATS = ["01_pleadings","02_orders","03_requests_responses","04_custodian_files","05_email_families",
        "06_chat_exports","07_privilege_material","08_production_logs","09_depositions",
        "10_expert_material","11_third_party","12_case_management"]
ROLES = ["identity_crosswalk","operative_authority","current_operations","approval_and_capacity",
         "correspondence","financial_or_population_support","chronology_and_custody","independent_counterrecord"]
FMTS = [".md",".txt",".eml",".csv",".json",".xml",".html",".pdf"]

def file_text(n):
    cat = CATS[(n-1)//8]; stem = cat.split("_",1)[1]; fmt = FMTS[(n-1)%8]
    p = os.path.join(base, cat, f"{n:03d}_{stem}_source_export{fmt}")
    if fmt == ".pdf":
        return "\n".join(pg.extract_text() or "" for pg in PdfReader(p).pages)
    return open(p, encoding="utf-8", errors="replace").read()

def get_body(text):
    for pat in [r"(?is)NATIVE RECORD\s*\n\s*(.+?)(?=\n\s*(?:RELIANCE LIMITS|SOURCE THREAD|\Z))",
                r"(?is)<native-record>(.*?)</native-record>",
                r'(?is)"body","((?:[^"\\]|\\.)*)"',
                r"(?is)Content-Type: text/plain; charset=utf-8\s*\n\s*\n(.+?)\n\nSOURCE LINEAGE"]:
        m = re.search(pat, text)
        if m: return m.group(1).strip().replace("\\n"," ").replace("\n"," ")
    return ""

def get_rev(text, kind):
    m = re.search(r"(?is)"+kind+r"[-_ ]revision\D{0,6}(REV-\d{4}\.\d)", text)
    return m.group(1) if m else None

CANON = {1:("ENT-031-1000","REV-2025.1"),2:("ENT-031-1001","REV-2025.2"),3:("ENT-031-1002","REV-2025.3"),
         4:("ENT-031-1003","REV-2025.4"),5:("ENT-031-1004","REV-2025.5"),6:("ENT-031-1005","REV-2025.6"),
         7:("ENT-031-1006","REV-2025.7"),8:("ENT-031-1007","REV-2025.1"),9:("ENT-031-1008","REV-2025.2"),
         10:("ENT-031-1009","REV-2024.2"),11:("ENT-031-1010","REV-2025.4"),12:("ENT-031-1011","REV-2025.5")}

out = {}
for n in range(1,97):
    key=(n-1)%12+1; role=ROLES[(n-1)//12]; text=file_text(n)
    out[(key,role)] = dict(n=n, body=get_body(text), ref=get_rev(text,"referenced"), cur=get_rev(text,"current"),
                           entities=set(re.findall(r"ENT-031-\d{4}", text)))

def flags(key, role):
    ce,cr = CANON[key]
    d = out[(key,role)]; b = d['body']
    f=[]
    if ce not in d['entities'] and d['entities']: f.append("ENT_ABSENT")
    if "ENT-031-2" in b or (f"ENT-031-2" in " ".join(d['entities'])): f.append("LOOKALIKE")
    if "collision" in b: f.append("COLLISION")
    if "blocks completion" in b: f.append("BLOCKS")
    if "open and unresolved" in b or "status is open" in b: f.append("OPEN")
    if "pending approval" in b or "remaining matter capacity is 0" in b: f.append("PENDING_0CAP")
    if d['ref'] and d['cur'] and d['ref']!=d['cur']: f.append("REVMISMATCH")
    return ",".join(f) if f else "OK"

print("== COMPACT MATRIX ==")
for k in range(1,13):
    f=[flags(k,r) for r in ROLES[:4]]
    print(f"CBP-031-{k:02d} ID[{f[0]}] OP[{f[1]}] CU[{f[2]}] AP[{f[3]}]")

# Save full bodies to a JSON file in sandbox for reference
with open("/tmp/aurora_matrix.json","w") as fh:
    json.dump({f"{k}:{r}":{**v,'entities':list(v['entities'])} for (k,r),v in out.items()}, fh, indent=0)
print("saved /tmp/aurora_matrix.json")

# print full bodies for keys 7-12 core controls
print("\n== FULL CORE BODIES keys 07-12 ==")
for k in range(7,13):
    for r in ROLES[:4]:
        d = out[(k,r)]
        print(f"  {k} {r[:12]:12s} ref={d['ref']} cur={d['cur']} ents={sorted(d['entities'])} :: {d['body'][:170]}")
"}

